:root {
  --bg-card: #1a1035;
  --bg-header: #2d1b6e;
  --bg-detail: #241447;
  --accent-gold: #f5c842;
  --accent-orange: #ff7a2f;
  --text-primary: #f0eaff;
  --text-muted: #a896d4;
  --badge-bg: #f5c842;
  --badge-text: #1a1035;
  --footer-bg: #2d1b6e;
  --border-color: #4a2fa0;
  --warning-text: #ffcf7a;
}

.eclipse-pass {
  background-color: var(--bg-card);
  border: 2px solid var(--border-color);
  border-radius: 16px;
  width: 400px;
  overflow: hidden;
  margin: 40px auto;
}

.pass-header {
  background-color: var(--bg-header);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  border-bottom: 2px solid var(--border-color);
}

.eclipse-icon {
  font-size: 36px;
  line-height: 1;
}

.pass-title {
  flex: 1;
}

.pass-title h1 {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.pass-subtitle {
  margin: 2px 0 0;
  font-size: 12px;
  color: var(--text-muted);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pass-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 13px;
  font-weight: 800;
  padding: 4px 10px;
  border-radius: 20px;
}

.pass-details {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 14px 20px;
}

.detail-item {
  background-color: var(--bg-detail);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  border-radius: 8px;
}

.detail-label {
  font-size: 12px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
}

.detail-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--accent-gold);
}

.pass-footer {
  background-color: var(--footer-bg);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  border-top: 2px solid var(--border-color);
}

.warning-icon {
  font-size: 16px;
  line-height: 1;
}

.warning-text {
  margin: 0;
  font-size: 12px;
  color: var(--warning-text);
  font-weight: 500;
}
